/* copiato da floppy-web/src/firmware-data.js da build.py: non modificare qui */
/* generato da build.py: firmware del Pro Micro (binario in base64) e sorgenti di RFIEC */
(function (RF) { RF.FIRMWARE = {"rfiec": {"name": "RFIEC 2.6", "file": "rfiec-v2.6.hex", "b64": ""}, "xum1541": {"name": "XUM1541 v08 PROMICRO", "file": "xum1541-PROMICRO-v08.hex", "b64": ""}, "xum1541_7406": {"name": "XUM1541 v08 PROMICRO_7406", "file": "xum1541-PROMICRO_7406-v08.hex", "b64": ""}}; RF.FIRMWARE_SRC = {"rfiec.ino": "// RetroFixer RFIEC \u2013 il PC fa da drive (e da stampante) per il Commodore 64, oppure comanda drive e stampanti veri\n// ---------------------------------------------------------------------------\n// Firmware per Arduino Pro Micro (ATmega32U4, 5 V / 16 MHz) collegato al bus seriale IEC\n// con gli stessi fili della XUM1541 \"PROMICRO\" (nessun componente in pi\u00f9):\n//\n//   Pro Micro   segnale   pin DIN IEC\n//   16 (PB2)    DATA      5\n//   14 (PB3)    CLK       4\n//    8 (PB4)    ATN       3\n//    9 (PB5)    SRQ       1\n//   10 (PB6)    RESET     6   (letto come dispositivo, tirato a zero dal reset in modalit\u00e0 padrone)\n//   GND         GND       2\n//\n// Il Pro Micro fa la parte del DISPOSITIVO (drive o stampante): i tempi del bus li gestisce la\n// libreria IECDevice di David Hansel (GPL-3, https://github.com/dhansel/IECDevice); il firmware\n// passa al browser ogni evento del bus (LISTEN, TALK, dati, UNLISTEN, UNTALK) attraverso la seriale\n// USB, e il browser risponde con i dati del disco (il \"DOS\" sta nella pagina web).\n//\n// Dalla versione 2.0 c'\u00e8 anche la modalit\u00e0 PADRONE DEL BUS (comando 'M' 1): il Pro Micro fa quello che fa la XUM1541,\n// cio\u00e8 comanda il bus al posto del C64 (LISTEN, TALK, dati, UNLISTEN, UNTALK) per leggere e scrivere sui drive veri o\n// stampare su una stampante vera. I tempi sono quelli del bus seriale Commodore; il codice \u00e8 scritto qui da zero.\n//\n// Protocollo (binario, sulla seriale USB; la velocit\u00e0 impostata non conta):\n//   PC \u2192 Pro Micro\n//     'V'                              chiede la versione \u2192 risposta 'H'\n//     'C' slot dev flags               configura lo slot 0 (drive) o 1 (stampante): numero e attivazione (bit 0)\n//     'D' slot seq len flags dati[len] dati da mandare al C64 (len \u2264 64); flags bit0 = fine file, bit1 = nessun dato\n//     'F' slot loader proto            avvia un caricatore veloce riconosciuto dalla pagina (loader 2 = Final Cartridge III;\n//                                      proto 1 LOAD e 5 LOADIMG leggono il canale 0, 2 SAVE scrive sul canale 1;\n//                                      loader 1 = Epyx FastLoad, proto 3: il nome del file arriva dal caricatore)\n//     'M' modo                         0 = dispositivo (drive/stampante emulati), 1 = padrone del bus \u2192 risposta 'm' modo\n//   solo in modalit\u00e0 padrone del bus:\n//     'A' len flags byte[len]          byte sotto ATN (LISTEN/TALK/OPEN/CLOSE/UNLISTEN/UNTALK); flags bit0 = dopo c'\u00e8 un TALK:\n//                                      il PC diventa ascoltatore \u2192 risposta 'a' n err (byte accettati, 0 = nessun dispositivo;\n//                                      err: 0 bene, 1 nessuno tira DATA, 2 chi ascolta non si libera, 3 byte non confermato,\n//                                      4 il dispositivo non prende CLK dopo il TALK)\n//     'B' len flags byte[len]          dati per chi ascolta; flags bit0 = EOI sull'ultimo byte \u2192 risposta 'b' n\n//     'G' lo hi                        legge fino a lo+hi*256 byte da chi parla \u2192 risposte 'g' n flags byte[n] (n \u2264 60;\n//                                      flags bit0 = EOI ricevuto, bit1 = ultimo pezzo); si ferma dopo 1 s senza dati\n//     'X'                              RESET del bus (la linea RESET a zero per 100 ms) \u2192 risposta 'x'\n//     'S'                              misura delle linee \u2192 risposta 's' a b c d (porta B del 32U4: a = a riposo,\n//                                      b = a riposo con i pull-up interni, c = con ATN e CLK tirati dopo 1 ms,\n//                                      d = 100 ms dopo aver liberato tutto; bit 2 DATA, 3 CLK, 4 ATN, 6 RESET, 1 = alta)\n//   Pro Micro \u2192 PC\n//     'H' len testo                    versione del firmware\n//     'L' slot sec                     LISTEN con indirizzo secondario (0x6n dati, 0xEn CLOSE, 0xFn OPEN)\n//     'T' slot sec seq                 TALK (seq: numero della sessione di TALK)\n//     'U' slot                         UNLISTEN\n//     'K' slot seq lo hi               UNTALK: quanti byte il C64 ha letto davvero in questa sessione\n//     'W' slot len eoi dati[len]       byte mandati dal C64 (len \u2264 32)\n//     'Q' slot seq                     servono altri dati per il TALK in corso\n//     'R'                              la linea RESET del bus \u00e8 andata a zero\n//\n// Licenza: GPL-3.0 (come IECDevice).\n\n#include <Arduino.h>\n#include <util/delay.h>\n#include <IECDevice.h>\n#include <IECBusHandler.h>\n\n#define PIN_ATN    8\n#define PIN_CLK   14\n#define PIN_DATA  16\n#define PIN_RESET 10\n#define PIN_SRQ    9\n\n#define FW_VERSION \"RFIEC 2.6\"\n\n// Porta seriale aperta dal PC. NON usare \"(bool) Serial\" sul 32U4: contiene un delay(10), e la libreria\n// chiama isActive() mentre il C64 manda l'indirizzo sotto ATN (che va confermato entro 1 ms).\nstatic bool hostUp = false;\nstatic bool lineUp() { return Serial.dtr() || Serial.rts(); }\n\n// ---------------- coda verso il PC ----------------\n#define OQ_SIZE 256\nstatic uint8_t  oq[OQ_SIZE];\nstatic uint16_t oqHead = 0, oqTail = 0;\nstatic uint16_t oqUsed() { return (uint16_t)(oqHead - oqTail); }\nstatic uint16_t oqFree() { return OQ_SIZE - oqUsed(); }\nstatic bool oqPut(const uint8_t *b, uint8_t n)\n{\n  if( oqFree() < n ) return false;\n  for(uint8_t i=0; i<n; i++) oq[(oqHead++) % OQ_SIZE] = b[i];\n  return true;\n}\nstatic void oqPump()\n{\n  uint16_t n = oqUsed();\n  if( n==0 || !hostUp ) return;\n  int room = Serial.availableForWrite();\n  if( room <= 0 ) return;\n  uint8_t chunk[32];\n  uint8_t k = 0;\n  while( k < sizeof(chunk) && k < (uint16_t) room && k < n ) chunk[k++] = oq[(oqTail++) % OQ_SIZE];\n  Serial.write(chunk, k);\n}\n\n// ---------------- padrone del bus (come la XUM1541) ----------------\n// Linee open collector sulla porta B: \"tirata\" = uscita a zero, \"libera\" = ingresso senza pull-up (le resistenze\n// le hanno il drive e la stampante). Le attese brevi si fanno a interrupt spenti e si contano in microsecondi.\n#define LN_DATA _BV(2)   // PB2 = pin 16\n#define LN_CLK  _BV(3)   // PB3 = pin 14\n#define LN_ATN  _BV(4)   // PB4 = pin 8\n#define LN_RST  _BV(6)   // PB6 = pin 10\nstatic bool master = false;\nstatic inline void lnLow(uint8_t m)  { PORTB &= ~m; DDRB |= m; }\nstatic inline void lnFree(uint8_t m) { DDRB &= ~m; PORTB &= ~m; }\nstatic inline bool lnIsLow(uint8_t m) { return (PINB & m) == 0; }\nstatic void lnFreeAll() { lnFree(LN_DATA | LN_CLK | LN_ATN | LN_RST); }\n// attesa breve (interrupt spenti): vero se la linea arriva allo stato voluto entro us microsecondi\n// (delayMicroseconds(1) sul 16 MHz non aspetta quasi niente: si usa _delay_us, un ciclo di attesa esatto)\nstatic bool waitShort(uint8_t m, bool low, uint16_t us)\n{\n  for( uint16_t n = 0; n < us; n++ ) { if( lnIsLow(m) == low ) return true; _delay_us(1); }\n  return lnIsLow(m) == low;\n}\nstatic uint8_t mErr = 0;\n// attesa lunga (interrupt accesi), in millisecondi; si interrompe se la pagina chiude la porta seriale\nstatic bool waitLong(uint8_t m, bool low, uint16_t ms)\n{\n  unsigned long t0 = millis();\n  uint8_t k = 0;\n  while( lnIsLow(m) != low )\n    {\n      if( millis() - t0 > ms ) return false;\n      if( ++k==0 && !(Serial.dtr() || Serial.rts()) ) return false;\n    }\n  return true;\n}\n// un byte da \"parlatore\": 0 = ricevuto, 1 = chi ascolta non \u00e8 pronto, 2 = nessuna conferma\nstatic uint8_t mSendByte(uint8_t b, bool eoi, uint16_t readyMs)\n{\n  lnFree(LN_CLK);                                   // pronto a mandare\n  if( !waitLong(LN_DATA, false, readyMs) ) { mErr = 2; return 1; }  // chi ascolta libera DATA quando \u00e8 pronto\n  noInterrupts();\n  if( eoi )\n    {\n      // EOI: si aspetta senza tirare CLK; chi ascolta lo conferma tirando DATA per almeno 60 us\n      if( !waitShort(LN_DATA, true, 2000) || !waitShort(LN_DATA, false, 2000) ) { interrupts(); return 2; }\n    }\n  lnLow(LN_CLK);\n  // tempi come nella XUM1541 di OpenCBM: CLK resta basso 75 us prima di ogni bit (il 1541 non regge i 20 us\n  // minimi delle specifiche), il bit si mette 2 us prima di liberare CLK e resta valido 20 us\n  for( uint8_t i = 0; i < 8; i++ )\n    {\n      delayMicroseconds(75);\n      if( !(b & 1) ) { lnLow(LN_DATA); _delay_us(2); }\n      lnFree(LN_CLK);                                 // bit valido\n      delayMicroseconds(20);\n      lnLow(LN_CLK);\n      lnFree(LN_DATA);\n      b >>= 1;\n    }\n  bool ack = waitShort(LN_DATA, true, 2000);        // conferma del byte (1 ms per le specifiche, si tollera il doppio)\n  interrupts();\n  delayMicroseconds(100);\n  if( !ack ) mErr = 3;\n  return ack ? 0 : 2;\n}\n// byte sotto ATN; talk: dopo l'ultimo il PC diventa ascoltatore (il dispositivo prende CLK)\nstatic uint8_t mAtn(const uint8_t *b, uint8_t n, bool talk)\n{\n  lnFree(LN_DATA); lnLow(LN_CLK); lnLow(LN_ATN);\n  mErr = 0;\n  // i dispositivi rispondono tirando DATA entro 1 ms (si aspetta fino a 2 ms, come la XUM1541)\n  if( !waitShort(LN_DATA, true, 2000) ) { lnFree(LN_ATN); lnFree(LN_CLK); mErr = 1; return 0; }   // nessun dispositivo\n  delayMicroseconds(40);\n  uint8_t sent = 0;\n  // un drive occupato (per esempio mentre legge la directory dopo un OPEN) risponde all'ATN solo quando ha finito:\n  // come la XUM1541 si aspetta che sia pronto (qui fino a 30 s)\n  while( sent < n && mSendByte(b[sent], false, 30000)==0 ) sent++;\n  if( sent < n ) { delayMicroseconds(20); lnFreeAll(); return sent; }   // byte non passato: si libera il bus\n  if( talk && sent==n )\n    {\n      // inversione dei ruoli: il PC tira DATA e libera ATN e CLK, poi il drive prende CLK quando ha finito di\n      // gestire l'ATN. Il 1541 ci mette alcuni millisecondi (il Kernal del C64 aspetta senza limite): fino a 100 ms.\n      lnLow(LN_DATA); delayMicroseconds(20); lnFree(LN_ATN); lnFree(LN_CLK);\n      if( !waitLong(LN_CLK, true, 100) ) { lnFreeAll(); mErr = 4; return 0; }\n    }\n  else\n    {\n      delayMicroseconds(20);\n      lnFree(LN_ATN);\n      // dopo UNLISTEN o UNTALK il bus torna libero; dopo LISTEN il PC resta parlatore (tiene CLK)\n      if( sent==0 || b[sent-1]==0x3F || b[sent-1]==0x5F ) { delayMicroseconds(100); lnFree(LN_CLK); lnFree(LN_DATA); }\n    }\n  return sent;\n}\n// un byte da \"ascoltatore\": -1 = chi parla non \u00e8 pronto (dopo readyMs), -2 = errore, altrimenti byte | 0x100 se EOI\nstatic int16_t mRecvByte(uint16_t readyMs)\n{\n  if( !waitLong(LN_CLK, false, readyMs) ) return -1; // chi parla libera CLK quando \u00e8 pronto\n  bool eoi = false;\n  noInterrupts();\n  lnFree(LN_DATA);                                  // pronti a ricevere\n  if( !waitShort(LN_CLK, true, 400) )\n    {\n      // niente bit entro 200 us: \u00e8 l'ultimo byte (EOI), lo confermiamo tirando DATA per 70 us\n      eoi = true;\n      lnLow(LN_DATA); delayMicroseconds(70); lnFree(LN_DATA);\n      if( !waitShort(LN_CLK, true, 2000) ) { interrupts(); return -2; }\n    }\n  uint8_t b = 0;\n  for( uint8_t i = 0; i < 8; i++ )\n    {\n      if( !waitShort(LN_CLK, false, 1000) ) { interrupts(); return -2; }\n      if( !lnIsLow(LN_DATA) ) b |= (1 << i);\n      if( !waitShort(LN_CLK, true, 1000) ) { interrupts(); return -2; }\n    }\n  lnLow(LN_DATA);                                   // byte ricevuto\n  interrupts();\n  delayMicroseconds(50);\n  return (int16_t) b | (eoi ? 0x100 : 0);\n}\nstatic void oqWait(uint8_t need) { while( oqFree() < need && hostUp ) { oqPump(); hostUp = Serial.dtr() || Serial.rts(); } }\nstatic void mRead(uint16_t len)\n{\n  uint8_t buf[60], k = 0, flags = 0;\n  for( uint16_t got = 0; got < len; got++ )\n    {\n      int16_t r = mRecvByte(1000);\n      if( r < 0 ) break;\n      buf[k++] = r & 0xFF;\n      if( r & 0x100 ) { flags = 1; break; }\n      if( k==sizeof(buf) ) { uint8_t h[3] = {'g', k, 0}; oqWait(3 + k); oqPut(h, 3); oqPut(buf, k); oqPump(); k = 0; }\n    }\n  uint8_t h[3] = {'g', k, (uint8_t) (flags | 2)};\n  oqWait(3 + k); oqPut(h, 3); oqPut(buf, k);\n}\nstatic void mWrite(const uint8_t *b, uint8_t n, bool eoiLast)\n{\n  uint8_t sent = 0;\n  while( sent < n && mSendByte(b[sent], eoiLast && sent==n-1, 30000)==0 ) sent++;\n  uint8_t r[2] = {'b', sent};\n  oqWait(2); oqPut(r, 2);\n}\nstatic void setMaster(bool on)\n{\n  lnFreeAll();\n  master = on;\n  uint8_t r[2] = {'m', (uint8_t) on};\n  oqPut(r, 2);\n}\n\nstatic void pumpInput();\nstatic void serviceHost() { pumpInput(); oqPump(); }\n\n// ---------------- dispositivo sul bus ----------------\n#define RB_SIZE 160\nclass RFDevice : public IECDevice\n{\n public:\n  RFDevice(uint8_t slot, uint8_t devnr) : IECDevice(devnr), m_slot(slot), m_enabled(false) {}\n\n  uint8_t  m_slot;\n  bool     m_enabled;\n  // dati da mandare al C64 (TALK)\n  uint8_t  rb[RB_SIZE];\n  uint8_t  rbHead = 0, rbCount = 0;\n  bool     talking = false, more = false, pending = false, noData = false;\n  uint8_t  seq = 0, talkSec = 0;\n  uint16_t consumed = 0;\n  // dati ricevuti dal C64 (LISTEN), spediti al PC a pezzi da 32 byte\n  uint8_t  wb[32];\n  uint8_t  wlen = 0;\n\n  virtual bool isActive() { return m_enabled && hostUp; }\n\n  void flushWrite(bool eoi)\n  {\n    if( wlen==0 && !eoi ) return;\n    uint8_t h[4] = {'W', m_slot, wlen, (uint8_t) (eoi ? 1 : 0)};\n    oqPut(h, 4);\n    oqPut(wb, wlen);\n    wlen = 0;\n  }\n\n  void dataFromHost(uint8_t s, const uint8_t *d, uint8_t n, uint8_t flags)\n  {\n    if( !talking || s!=seq ) return;          // risposta di una sessione gi\u00e0 chiusa\n    pending = false;\n    for(uint8_t i=0; i<n && rbCount<RB_SIZE; i++) rb[(rbHead + rbCount++) % RB_SIZE] = d[i];\n    if( flags & 1 ) more = false;\n    if( flags & 2 ) { more = false; noData = (rbCount==0); }\n  }\n\n  void prefetch()\n  {\n    if( talking && more && !pending && rbCount < RB_SIZE - 64 )\n      {\n        uint8_t q[3] = {'Q', m_slot, seq};\n        if( oqPut(q, 3) ) pending = true;\n      }\n  }\n\n protected:\n  virtual void reset()\n  {\n    talking = false; rbCount = 0; wlen = 0;\n    if( m_slot==0 ) { uint8_t r = 'R'; oqPut(&r, 1); }\n  }\n\n public:\n  // caricatore veloce chiesto dalla pagina (Final Cartridge III)\n  void startFast(uint8_t loader, uint8_t proto)\n  {\n#ifdef IEC_FP_EPYX\n    // Epyx: la libreria riceve il nome del file, lo apre sul canale 0 (listen/write/unlisten) e poi chiede i dati\n    if( loader==IEC_FP_EPYX && proto==IEC_FL_PROT_HEADER ) { fastLoadRequest(loader, proto); return; }\n#endif\n#ifdef IEC_FP_FC3\n    if( loader!=IEC_FP_FC3 ) return;\n    if( proto==IEC_FL_PROT_LOAD || proto==IEC_FL_PROT_LOADIMG )\n      talk(0x60);                             // i dati arrivano dal canale 0, come un TALK normale\n    else if( proto==IEC_FL_PROT_SAVE )\n      listen(0x61);                           // i dati vanno al canale 1 (il file aperto con SAVE)\n    else\n      return;\n    fastLoadRequest(loader, proto);\n#endif\n  }\n\n  // trasferimenti a blocchi (JiffyDOS, Final Cartridge III): qui si pu\u00f2 aspettare il PC quanto serve\n  virtual uint8_t read(uint8_t *buffer, uint8_t n)\n  {\n    uint8_t got = 0;\n    unsigned long t0 = millis();\n    while( got < n )\n      {\n        if( rbCount )\n          {\n            buffer[got++] = rb[rbHead];\n            rbHead = (rbHead + 1) % RB_SIZE; rbCount--; consumed++;\n            t0 = millis();\n            continue;\n          }\n        if( !talking ) talk(0x60);           // primo blocco di un caricatore veloce: dati dal canale 0\n        if( !more || !hostUp || millis()-t0 > 3000 ) break;\n        prefetch();\n        serviceHost();\n      }\n    return got;\n  }\n\n  virtual uint8_t write(uint8_t *buffer, uint8_t n, bool eoi)\n  {\n    unsigned long t0 = millis();\n    for(uint8_t i=0; i<n; i++)\n      {\n        while( canWrite() < 0 )\n          {\n            if( !hostUp || millis()-t0 > 3000 ) return i;\n            serviceHost();\n          }\n        write(buffer[i], eoi && i==n-1);\n        t0 = millis();\n      }\n    return n;\n  }\n\n protected:\n  virtual void listen(uint8_t secondary)\n  {\n    if( talking ) untalk();                   // fine di un TALK veloce (il C64 non manda UNTALK)\n    flushWrite(false);\n    wlen = 0;\n    uint8_t f[3] = {'L', m_slot, secondary};\n    oqPut(f, 3);\n  }\n\n  virtual void unlisten()\n  {\n    flushWrite(false);\n    uint8_t f[2] = {'U', m_slot};\n    oqPut(f, 2);\n  }\n\n  virtual void talk(uint8_t secondary)\n  {\n    secondary = 0x60 | (secondary & 0x0F);\n    // l'Epyx FastLoad chiama talk(0) prima di ogni blocco: \u00e8 lo stesso TALK che continua\n    if( talking && secondary==talkSec ) return;\n    talkSec = secondary;\n    seq++;\n    talking = true; more = true; pending = false; noData = false;\n    rbHead = 0; rbCount = 0; consumed = 0;\n    uint8_t f[4] = {'T', m_slot, secondary, seq};\n    if( oqPut(f, 4) ) pending = true;         // il PC risponde a 'T' mandando i primi dati\n  }\n\n  virtual void untalk()\n  {\n    uint8_t f[5] = {'K', m_slot, seq, (uint8_t) (consumed & 0xFF), (uint8_t) (consumed >> 8)};\n    oqPut(f, 5);\n    talking = false; rbCount = 0; more = false; pending = false;\n  }\n\n  virtual int8_t canWrite()\n  {\n    return oqFree() >= 48 ? 1 : -1;\n  }\n\n  virtual void write(uint8_t data, bool eoi)\n  {\n    wb[wlen++] = data;\n    if( eoi || wlen==sizeof(wb) ) flushWrite(eoi);\n  }\n\n  virtual int8_t canRead()\n  {\n    if( rbCount >= 2 ) return rbCount > 127 ? 127 : (int8_t) rbCount;\n    if( rbCount==1 && !more ) return 1;       // ultimo byte: la libreria lo manda con EOI\n    if( rbCount==0 && !more ) return 0;       // niente da mandare (per esempio file non trovato)\n    prefetch();\n    return -1;                                // aspetta i dati dal PC tenendo occupato il bus\n  }\n\n  virtual uint8_t peek()\n  {\n    return rbCount ? rb[rbHead] : 0;\n  }\n\n  virtual uint8_t read()\n  {\n    if( rbCount==0 ) return 0;\n    uint8_t d = rb[rbHead];\n    rbHead = (rbHead + 1) % RB_SIZE; rbCount--; consumed++;\n    return d;\n  }\n};\n\nstatic RFDevice drive(0, 8), printer(1, 4);\nstatic RFDevice *devs[2] = {&drive, &printer};\nstatic IECBusHandler bus(PIN_ATN, PIN_CLK, PIN_DATA, PIN_RESET, 0xFF, PIN_SRQ);\n\n// ---------------- comandi dal PC ----------------\nstatic uint8_t ib[72];\nstatic uint8_t ibLen = 0;\n\nstatic uint8_t frameLen(const uint8_t *b, uint8_t n)\n{\n  // restituisce la lunghezza del comando se \u00e8 completo, 0 se ne mancano ancora pezzi\n  switch( b[0] )\n    {\n    case 'V': return 1;\n    case 'C': return n >= 4 ? 4 : 0;\n    case 'D': if( n < 5 ) return 0; return (n >= 5 + b[3]) ? 5 + b[3] : 0;\n    case 'F': return n >= 4 ? 4 : 0;\n    case 'M': return n >= 2 ? 2 : 0;\n    case 'A': case 'B': if( n < 3 ) return 0; return (n >= 3 + b[1]) ? 3 + b[1] : 0;\n    case 'G': return n >= 3 ? 3 : 0;\n    case 'X': return 1;\n    case 'S': return 1;\n    default:  return 1;                       // byte sconosciuto: si scarta\n    }\n}\n\nstatic void handleFrame(const uint8_t *b, uint8_t n)\n{\n  if( b[0]=='V' )\n    {\n      const char *v = FW_VERSION;\n      uint8_t h[2] = {'H', (uint8_t) strlen(v)};\n      oqPut(h, 2); oqPut((const uint8_t *) v, strlen(v));\n    }\n  else if( b[0]=='C' && b[1] < 2 )\n    {\n      devs[b[1]]->setDeviceNumber(b[2]);\n      devs[b[1]]->m_enabled = (b[3] & 1)!=0;\n    }\n  else if( b[0]=='D' && b[1] < 2 && b[3] <= 64 )\n    devs[b[1]]->dataFromHost(b[2], b + 5, b[3], b[4]);\n  else if( b[0]=='F' && b[1]==0 )\n    drive.startFast(b[2], b[3]);\n  else if( b[0]=='M' )\n    {\n      // padrone del bus: i dispositivi emulati tacciono e la libreria non guarda pi\u00f9 il bus\n      drive.m_enabled = printer.m_enabled = false;\n      setMaster(b[1]==1);\n    }\n  else if( master && b[0]=='A' && b[1] <= 64 )\n    {\n      uint8_t n = mAtn(b + 3, b[1], (b[2] & 1)!=0);\n      uint8_t r[3] = {'a', n, mErr};\n      oqWait(3); oqPut(r, 3);\n    }\n  else if( master && b[0]=='B' && b[1] <= 64 )\n    mWrite(b + 3, b[1], (b[2] & 1)!=0);\n  else if( master && b[0]=='G' )\n    mRead(b[1] | (b[2] << 8));\n  else if( master && b[0]=='S' )\n    {\n      uint8_t r[5] = {'s', 0, 0, 0, 0};\n      lnFreeAll(); delayMicroseconds(200); r[1] = PINB;\n      PORTB |= LN_DATA | LN_CLK | LN_ATN | LN_RST; delayMicroseconds(200); r[2] = PINB; lnFreeAll();\n      lnLow(LN_ATN); lnLow(LN_CLK); delayMicroseconds(1000); r[3] = PINB;\n      lnFreeAll(); delay(100); r[4] = PINB;\n      oqWait(5); oqPut(r, 5);\n    }\n  else if( master && b[0]=='X' )\n    {\n      lnFreeAll(); lnLow(LN_RST); delay(100); lnFree(LN_RST);\n      uint8_t r = 'x'; oqPut(&r, 1);\n    }\n}\n\nstatic void pumpInput()\n{\n  // al massimo 64 byte per giro, per tornare presto a bus.task()\n  for(uint8_t k=0; k<64 && Serial.available(); k++)\n    {\n      if( ibLen < sizeof(ib) ) ib[ibLen++] = Serial.read(); else { ibLen = 0; continue; }\n      uint8_t fl = frameLen(ib, ibLen);\n      if( fl )\n        {\n          handleFrame(ib, fl);\n          ibLen = 0;\n        }\n    }\n}\n\nvoid setup()\n{\n  Serial.begin(115200);\n  bus.attachDevice(&drive);\n  bus.attachDevice(&printer);\n#ifdef IEC_FP_JIFFY\n  drive.enableFastLoader(IEC_FP_JIFFY, true);\n#endif\n#ifdef IEC_FP_FC3\n  drive.enableFastLoader(IEC_FP_FC3, true);\n#endif\n#ifdef IEC_FP_EPYX\n  drive.enableFastLoader(IEC_FP_EPYX, true);\n#endif\n  bus.begin();\n}\n\nvoid loop()\n{\n  // in modalit\u00e0 padrone il bus lo comandiamo noi: la libreria non deve rispondere al nostro ATN\n  if( !master ) bus.task();\n  bool up = lineUp();\n  if( up != hostUp )\n    {\n      // il PC ha aperto o chiuso la porta: si riparte da zero, i dispositivi si spengono finch\u00e9 il PC non li configura\n      hostUp = up; oqHead = oqTail = 0; ibLen = 0;\n      drive.m_enabled = printer.m_enabled = false;\n      if( master ) { lnFreeAll(); master = false; }\n    }\n  if( !up ) return;\n  pumpInput();\n  drive.prefetch();\n  oqPump();\n}\n", "IECConfig.h": "// -----------------------------------------------------------------------------\n// Copyright (C) 2024 David Hansel\n//\n// This program is free software; you can redistribute it and/or modify\n// it under the terms of the GNU General Public License as published by\n// the Free Software Foundation; either version 3 of the License, or\n// (at your option) any later version.\n//\n// This program is distributed in the hope that it will be useful,\n// but WITHOUT ANY WARRANTY; without even the implied warranty of\n// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n// GNU General Public License for more details.\n//\n// You should have receikved a copy of the GNU General Public License\n// along with this program; if not, write to the Free Software Foundation,\n// Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301  USA\n// -----------------------------------------------------------------------------\n\n#ifndef IECCONFIG_H\n#define IECCONFIG_H\n\n// un-comment this if you are using open-collector drivers for the CLK/DATA\n// lines (e.g. a 7406 or 7407). If so, the IECBusHandler constructor requires\n// two extra pins for the CLK/DATA output signals\n//#define IEC_USE_LINE_DRIVERS\n\n// un-comment this IN ADDITION to IEC_USE_LINE_DRIVERS if you are using inverted\n// line drivers (such as 7406)\n//#define IEC_USE_INVERTED_LINE_DRIVERS\n\n// un-comment this if you are using inverters on the IEC bus input signals\n// (only has an effect if IEC_USE_LINE_DRIVERS is also enabled)\n//#define IEC_USE_INVERTED_INPUTS\n\n// comment out these #defines to completely disable support for the\n// corresponding fast-load protocols (saves program memory in small devices)\n#define IEC_FP_JIFFY     0 // JiffyDos\n#define IEC_FP_EPYX      1 // EPYX FastLoad  (RetroFixer: attivato, il riconoscimento del caricatore lo fa la pagina)\n#define IEC_FP_FC3       2 // Final Cartridge 3 (RetroFixer: attivato, il riconoscimento del caricatore lo fa la pagina)\n//#define IEC_FP_AR6       3 // Action Replay 6\n//#define IEC_FP_DOLPHIN   4 // Dolphin Dos\n//#define IEC_FP_SPEEDDOS  5 // Speed Dos\n//#define IEC_FP_HYPRALOAD 6 // Hypra-Load (64er Magazin)\n\n// convenience macro, IEC_SUPPORT_FASTLOAD is defined if any fast-load protocols\n// are enabled\n#if defined(IEC_FP_JIFFY) || defined(IEC_FP_EPYX) || defined(IEC_FP_FC3) || defined(IEC_FP_AR6) || defined(IEC_FP_DOLPHIN) || defined(IEC_FP_SPEEDDOS) || defined(IEC_FP_HYPRALOAD)\n#define IEC_SUPPORT_FASTLOAD\n#endif\n\n// un-comment this to use a XRA1405 port expander for the 8-bit parallel cable\n// instead of connecting the parallel pins directly to the microcontroller\n//#define IEC_SUPPORT_PARALLEL_XRA1405\n\n// support Epyx FastLoad sector operations (disk editor, disk copy, file copy)\n// if this is enabled then the buffer in the setBuffer() call must have a size of\n// at least 256 bytes. Note that the \"bufferSize\" argument is a byte and therefore\n// capped at 255 bytes. Make sure the buffer itself has >=256 bytes and use a \n// bufferSize argument of 255 or less\n//#define IEC_FP_EPYX_SECTOROPS\n\n// defines the maximum number of devices that the bus handler will be\n// able to support - set to 4 by default but can be increased to up to 30 devices\n#define IEC_MAX_DEVICES 4\n\n// sets the default size of the fastload buffer. If this is set to 0 then fastload\n// protocols can only be used if the IECBusHandler::setBuffer() function is\n// called to define the buffer.\n#if defined(IEC_SUPPORT_FASTLOAD)\n#define IEC_DEFAULT_FASTLOAD_BUFFER_SIZE 128\n#endif\n\n// buffer size for IECFileDevice when receiving data. On channel 15, any command\n// longer than this (received in a single transaction) will be cut off.\n// For other channels, the device's write() function will be called once the\n// buffer is full. Every instance of IECFileDevice will allocate this buffer\n// so it should be kept small on platforms with little RAM (e.g. Arduino UNO)\n#define IECFILEDEVICE_WRITE_BUFFER_SIZE  64\n\n// buffer size for IECFileDevice transmitting data on channel 15, if\n// IECFileDevice::setStatus() is called with data longer than this it will be clipped.\n// every instance of IECFileDevice will allocate this buffer so it should be\n// kept small on platforms with little RAM (e.g. Arduino UNO)\n#define IECFILEDEVICE_STATUS_BUFFER_SIZE 40\n\n// convenience macro, IEC_SUPPORT_PARALLEL is defined if any of the supported\n// fast-load protocols use a parallel cable\n#if defined(IEC_FP_DOLPHIN) || defined(IEC_FP_SPEEDDOS)\n#define IEC_SUPPORT_PARALLEL\n#endif\n\n#endif\n"}; })(window.RFFloppy = window.RFFloppy || {});
